#!/bin/bash

# Jxion API - Quick PostgreSQL Setup Script
# This script helps you create the database and get your DATABASE_URL

echo "🔧 Jxion API - PostgreSQL Setup"
echo "================================"
echo ""

# Check if PostgreSQL is installed
if ! command -v psql &> /dev/null; then
    echo "❌ PostgreSQL is not installed or not in PATH"
    echo "Please install PostgreSQL first: https://www.postgresql.org/download/"
    exit 1
fi

echo "✅ PostgreSQL found: $(psql --version)"
echo ""

# Check if PostgreSQL is running
if ! pg_isready &> /dev/null; then
    echo "⚠️  PostgreSQL is not running"
    echo "Please start PostgreSQL first:"
    echo "  brew services start postgresql@18"
    echo "  OR check System Preferences > Extensions > PostgreSQL"
    exit 1
fi

echo "✅ PostgreSQL is running"
echo ""

# Get database name
read -p "Enter database name [jxion]: " DB_NAME
DB_NAME=${DB_NAME:-jxion}

# Get username
read -p "Enter PostgreSQL username [postgres]: " DB_USER
DB_USER=${DB_USER:-postgres}

# Get password (hidden input)
read -sp "Enter PostgreSQL password: " DB_PASS
echo ""

# Get host
read -p "Enter PostgreSQL host [localhost]: " DB_HOST
DB_HOST=${DB_HOST:-localhost}

# Get port
read -p "Enter PostgreSQL port [5432]: " DB_PORT
DB_PORT=${DB_PORT:-5432}

echo ""
echo "📝 Creating database..."

# Create database
if PGPASSWORD="$DB_PASS" createdb -h "$DB_HOST" -p "$DB_PORT" -U "$DB_USER" "$DB_NAME" 2>/dev/null; then
    echo "✅ Database '$DB_NAME' created successfully"
elif PGPASSWORD="$DB_PASS" psql -h "$DB_HOST" -p "$DB_PORT" -U "$DB_USER" -d postgres -c "CREATE DATABASE $DB_NAME;" 2>/dev/null; then
    echo "✅ Database '$DB_NAME' created successfully"
else
    echo "⚠️  Database might already exist or there was an error"
    echo "Continuing anyway..."
fi

echo ""

# URL encode password (basic)
URL_ENCODED_PASS=$(echo -n "$DB_PASS" | sed 's/@/%40/g; s/#/%23/g; s/\$/%24/g; s/%/%25/g; s/&/%26/g; s/+/%2B/g; s/=/%3D/g; s/?/%3F/g; s/\//%2F/g; s/:/%3A/g; s/ /%20/g')

# Build DATABASE_URL
DATABASE_URL="postgres://${DB_USER}:${URL_ENCODED_PASS}@${DB_HOST}:${DB_PORT}/${DB_NAME}?sslmode=disable"

